# Tuned per category, language and surface on labeled samples.
# auto: remove at/above it (precision target); review: send to the LLM (recall target).
BANDS = {
    "spam":      {"auto": 0.97,  "review": 0.80},
    "nudity":    {"auto": 0.98,  "review": 0.60},
    "hate":      {"auto": 0.995, "review": 0.40},  # context-heavy: lean on LLM + humans
    "self_harm": {"auto": None,  "review": 0.30},  # never auto-remove: route to support
}

def route(item, scores: dict[str, float]) -> str:
    if hash_bank.match(item.media_hashes):   # PhotoDNA / PDQ, milliseconds
        return "remove_and_report"
    borderline = False
    for cat, s in scores.items():
        band = BANDS[cat]
        if band["auto"] is not None and s >= band["auto"]:
            return f"remove:{cat}"
        borderline |= s >= band["review"]
    if borderline:
        return "llm_review"   # async; publish with limited distribution meanwhile
    return "allow"
